update public.learning_paths
set
  title = 'Data Journalism',
  goal = 'Data Journalism',
  summary = 'Finding, verifying, analyzing, visualizing, and publishing public-interest stories from data.',
  data = $dajojson${"slug": "data-journalism", "title": "Data Journalism", "description": "Finding, verifying, analyzing, visualizing, and publishing public-interest stories from data.", "topics": [{"id": "62f38083-0178-46e6-bdba-e009c84a8ae6", "type": "topic", "title": "Data Journalism Mindset and Story Discovery", "description": "Students learn to treat datasets as reporting leads, not as finished truth. The unit builds the habit of asking public-interest questions before opening a spreadsheet.", "children": [{"id": "7b84bce4-61e5-4daf-ac2a-0be50543a266", "type": "subtopic", "title": "What makes a data story newsworthy", "children": [{"id": "29db37a8-bbf7-43d6-9c2a-415aec4b1b00", "type": "concept", "title": "public-interest framing"}, {"id": "9ba43f45-587d-498b-810a-4c04b7dbf45d", "type": "concept", "title": "news values"}, {"id": "748c1155-cbdd-4b8b-9f7c-1487449883f2", "type": "concept", "title": "who benefits and who is harmed"}], "description": "Students connect data work to stakes, affected communities, accountability, novelty, and service journalism."}, {"id": "861d408e-afdb-4bb9-ab34-6ed7ae6e47b2", "type": "subtopic", "title": "From question to dataset", "children": [{"id": "d3062272-22f5-48fb-a21c-59c3a39e0ce1", "type": "concept", "title": "hypotheses"}, {"id": "55a36dc1-7373-4295-92de-797fbb77b032", "type": "concept", "title": "measurable indicators"}, {"id": "aec8226c-86cd-4889-9fab-4b426abbb32e", "type": "concept", "title": "scope and unit of analysis"}], "description": "The class practices turning fuzzy curiosities into answerable reporting questions and evidence plans."}, {"id": "4e07e1cf-deff-457f-a44c-870c331c3927", "type": "subtopic", "title": "Finding patterns and anomalies", "children": [{"id": "896993dd-b251-47cc-90e1-1755a9d95bda", "type": "concept", "title": "outlier spotting"}, {"id": "7259ea0f-99dd-4a6d-9492-608befb12f27", "type": "concept", "title": "trend detection"}, {"id": "ee96d59e-23b7-49ba-8a74-1c18be28683b", "type": "concept", "title": "localizing national data"}], "description": "Students learn to scan data for outliers, gaps, rankings, rates, change over time, and meaningful comparisons."}, {"id": "f5695f3a-f7b6-4792-a84e-9332845b91dc", "type": "subtopic", "title": "Reporting before analysis", "children": [{"id": "2031b3ba-30f2-4ab2-9ffb-4835ca1066cf", "type": "concept", "title": "source mapping"}, {"id": "e501e0a5-a0a5-49d3-8053-f8168f992f85", "type": "concept", "title": "pre-analysis interviews"}, {"id": "17d95122-6cc9-42d4-94ef-8567081e999d", "type": "concept", "title": "community context"}], "description": "Students interview experts and affected people early so the analysis is grounded in real-world context."}]}, {"id": "ca04fa38-e73c-474f-ad19-65d18932aa19", "type": "topic", "title": "Data Acquisition, Public Records, and Source Evaluation", "description": "This section teaches students where data comes from, how to obtain it, and how to judge whether it can support a publishable claim.", "children": [{"id": "7b0766b9-686b-4dbc-bd3c-9533814bbb72", "type": "subtopic", "title": "Public data sources", "children": [{"id": "bf698247-49b0-4ef6-8d6b-35361332b460", "type": "concept", "title": "Census data"}, {"id": "5438435c-0d92-4ae5-a875-052745aa4053", "type": "concept", "title": "local open-data portals"}, {"id": "2d4728e5-6d62-4cd6-95fe-a21ee7150ab3", "type": "concept", "title": "administrative records"}], "description": "Students become fluent in government, nonprofit, academic, and newsroom data repositories."}, {"id": "46a3d35d-2c7d-4b48-a1c5-1c1ce97863cc", "type": "subtopic", "title": "Records requests and FOIA strategy", "children": [{"id": "cafd2cea-2ece-444a-af27-670f41528344", "type": "concept", "title": "request wording"}, {"id": "b88bd9ef-b529-4c22-a296-a0707493302c", "type": "concept", "title": "fee waivers"}, {"id": "e8891cfd-cc83-4b15-af86-5f3e13300ba9", "type": "concept", "title": "appeals and follow-up"}], "description": "Students learn to request data precisely and negotiate for usable formats and metadata."}, {"id": "94cf79a4-d866-4174-9798-6abf7e3a07d7", "type": "subtopic", "title": "Data dictionaries and metadata", "children": [{"id": "8eec8ecd-c57f-4c09-bbd4-251369093b5d", "type": "concept", "title": "variable definitions"}, {"id": "0b468a45-a2c1-4378-b7cd-9f0d9ac0d449", "type": "concept", "title": "collection methods"}, {"id": "842b75ec-50da-4e88-8c14-937325f0217f", "type": "concept", "title": "missing-value codes"}], "description": "The course emphasizes reading documentation before analysis so fields, codes, and limitations are understood."}, {"id": "3e28b9b8-d743-4f47-9678-a3bf701a048d", "type": "subtopic", "title": "Source credibility and provenance", "children": [{"id": "95abac34-155b-4fe9-89ad-91d097b6d351", "type": "concept", "title": "primary vs. secondary sources"}, {"id": "438d727b-75c9-4856-99ca-883950a4de69", "type": "concept", "title": "methodological bias"}, {"id": "ec145c11-b3d0-4cd1-bf9b-69c417144866", "type": "concept", "title": "version history"}], "description": "Students learn to evaluate who collected data, why it exists, and what incentives shaped it."}]}, {"id": "9c005b99-293f-47de-875b-d6154fad754e", "type": "topic", "title": "Spreadsheet Reporting, Cleaning, and Data Quality", "description": "Spreadsheets remain the first professional tool for many data stories. This unit builds speed, discipline, and skepticism in everyday newsroom analysis.", "children": [{"id": "ded55363-dcb1-47b3-8eb5-327ff11445fc", "type": "subtopic", "title": "Spreadsheet fluency", "children": [{"id": "d416f966-7d98-4154-9f76-c044669ce952", "type": "concept", "title": "sorts and filters"}, {"id": "c760a3e6-43e5-4748-9319-58fdaae0da53", "type": "concept", "title": "pivot tables"}, {"id": "ba2c3a78-2121-44e7-af11-c8839e8b700a", "type": "concept", "title": "XLOOKUP/VLOOKUP"}], "description": "Students use sorting, filtering, formulas, pivot tables, and lookup functions to explore and summarize records."}, {"id": "ed321c32-e7ce-475a-9741-e85c6af918b4", "type": "subtopic", "title": "Cleaning messy data", "children": [{"id": "e44d4580-61ab-4a2d-9dad-8f6de49c45e6", "type": "concept", "title": "deduplication"}, {"id": "c0d15336-4555-40a6-86da-72f22fe35fba", "type": "concept", "title": "text-to-columns"}, {"id": "1cefbd6d-b516-4a58-b60d-107b7675e536", "type": "concept", "title": "date parsing"}], "description": "Students practice standardizing names, dates, categories, addresses, and numeric fields without destroying source material."}, {"id": "8a18dc56-a063-4c3c-9d3c-4f8261453c8e", "type": "subtopic", "title": "Data quality checks", "children": [{"id": "92a08987-387c-431f-a0dc-d45381fc834d", "type": "concept", "title": "null checks"}, {"id": "a567ccfa-eca7-4ebf-aff6-9d196084b569", "type": "concept", "title": "range checks"}, {"id": "9c066199-a396-4519-88a9-509986332c03", "type": "concept", "title": "duplicate detection"}], "description": "Students learn to test completeness, consistency, ranges, and duplicates before trusting results."}, {"id": "5d90ed52-8203-41ed-80ca-9923bd893d30", "type": "subtopic", "title": "Audit trails", "children": [{"id": "7e35470b-f6a2-4446-9664-f0534f9d41cc", "type": "concept", "title": "raw/working/output folders"}, {"id": "008399b7-4852-4d09-90a8-6527ea3f02d9", "type": "concept", "title": "change logs"}, {"id": "9c53e784-a669-4b99-a62f-00661d35ce79", "type": "concept", "title": "repeatable cleaning notes"}], "description": "Students keep raw data separate from working files and document every transformation."}]}, {"id": "722bc115-a077-4862-86dc-ab8e22060771", "type": "topic", "title": "Statistics and Numeracy for Journalists", "description": "Students learn enough statistics to avoid common errors, question official claims, and explain quantitative findings clearly to a general audience.", "children": [{"id": "cc293e85-2406-4cf9-9bd1-880703f8f9cb", "type": "subtopic", "title": "Counts, rates, ratios, and denominators", "children": [{"id": "d6d381fe-eb4c-47a5-9ce6-133e687bae33", "type": "concept", "title": "per-capita rates"}, {"id": "99e32502-c310-450d-a634-cbab666f6eb3", "type": "concept", "title": "base rates"}, {"id": "6fc08240-915f-449d-b510-a99de2ece513", "type": "concept", "title": "normalization"}], "description": "The unit stresses that most public claims depend on choosing the right denominator and comparison group."}, {"id": "619ab56b-8a61-4f0b-97ec-4ec6aa57b9ef", "type": "subtopic", "title": "Distributions and uncertainty", "children": [{"id": "cb2eec4f-d43a-45a7-9cbe-3bb9e9f93057", "type": "concept", "title": "median vs. mean"}, {"id": "acef388a-bd1a-4a2a-862b-38fde4ee01fe", "type": "concept", "title": "percentiles"}, {"id": "6ed1cb87-e832-4547-85aa-3b0bed6e30f9", "type": "concept", "title": "confidence intervals"}], "description": "Students move beyond averages by examining spread, skew, confidence, and uncertainty."}, {"id": "676ec385-c706-490f-bf32-2168d9e2a4f4", "type": "subtopic", "title": "Change over time", "children": [{"id": "92a48202-9bf6-498b-80da-7bd3750f4936", "type": "concept", "title": "percent change"}, {"id": "398a7508-685e-4d92-b8cf-65181f813264", "type": "concept", "title": "indexing"}, {"id": "eafe882f-d366-4814-8bbf-5feddd7b9fae", "type": "concept", "title": "moving averages"}], "description": "Students learn to distinguish real trends from seasonal noise, one-time shocks, and cherry-picked endpoints."}, {"id": "bd0869d8-6f3e-4536-b2fb-ededfbe7a6bc", "type": "subtopic", "title": "Polls, surveys, and sampling", "children": [{"id": "244db6b2-f5fb-4b0b-a620-9999b9a24597", "type": "concept", "title": "sampling frames"}, {"id": "49899dc0-dd6d-480b-bedf-d363b9cb93d6", "type": "concept", "title": "margin of error"}, {"id": "1691967a-2b04-49dc-ac3c-6927a2bd2988", "type": "concept", "title": "question wording"}], "description": "The class covers margins of error, sample quality, weighting, and what survey results can and cannot prove."}]}, {"id": "761bceac-6d52-42a3-8a13-eab1f18362ba", "type": "topic", "title": "SQL, Databases, and Relational Thinking", "description": "Data reporters need to move beyond single sheets. This unit introduces database logic for joining, grouping, and querying larger public records.", "children": [{"id": "ac834fc7-1356-43b4-bce4-422fd761cfed", "type": "subtopic", "title": "Relational data concepts", "children": [{"id": "5402f7c9-a246-4003-aec9-948709149553", "type": "concept", "title": "primary keys"}, {"id": "b6a306b2-df83-4b47-9d2f-40b23876578b", "type": "concept", "title": "foreign keys"}, {"id": "88882605-48f5-4451-9b19-fc3f4d7c828e", "type": "concept", "title": "one-to-many relationships"}], "description": "Students learn tables, keys, joins, and the difference between records, entities, and events."}, {"id": "5d04884d-7e63-4709-973e-42948e6570cf", "type": "subtopic", "title": "Core SQL queries", "children": [{"id": "d7a0e2ed-1780-45af-8787-f27a0da34ff2", "type": "concept", "title": "SELECT and WHERE"}, {"id": "9420c289-51f5-406b-b9d2-f08bdaebf817", "type": "concept", "title": "GROUP BY"}, {"id": "09e6a431-d96d-4709-92ee-e232f16bdc29", "type": "concept", "title": "COUNT, SUM, AVG"}], "description": "Students practice selecting, filtering, grouping, ordering, and aggregating records."}, {"id": "681fa43d-05b3-4ad6-afc0-f727734b7063", "type": "subtopic", "title": "Joining datasets", "children": [{"id": "0be75df4-72e5-4cd0-99e2-5db765ac4b2c", "type": "concept", "title": "inner/left joins"}, {"id": "8b15e4aa-b1d9-4895-b4a9-bb81a48930a6", "type": "concept", "title": "join keys"}, {"id": "428b438e-b8fc-46ec-a38c-fd2baae3a606", "type": "concept", "title": "merge validation"}], "description": "The class teaches when joins reveal relationships and when they create false matches."}, {"id": "9a4e59eb-b23d-4478-ad32-1b37ccbce341", "type": "subtopic", "title": "Database-backed reporting", "children": [{"id": "c1d7615e-a049-4874-b96a-1e94cf282e92", "type": "concept", "title": "SQLite"}, {"id": "bf814efb-41d9-4db0-a1de-da82abe04c06", "type": "concept", "title": "PostgreSQL concepts"}, {"id": "074ef4fd-2ae1-46a8-a76a-60d3f370201e", "type": "concept", "title": "query notebooks"}], "description": "Students learn when a database is the right tool for large, repeated, or collaborative analysis."}]}, {"id": "09f5f83c-425f-4618-b57f-71776ec9f916", "type": "topic", "title": "Python, Notebooks, and Reproducible Workflows", "description": "Coding is taught as a reporting amplifier: a way to make analysis repeatable, inspectable, and scalable, not as an end in itself.", "children": [{"id": "e09a8cdb-4e20-43ab-b292-2f600c514e11", "type": "subtopic", "title": "Notebook-based analysis", "children": [{"id": "fa02b0e2-e24c-4a2b-befa-0b3e86c6304f", "type": "concept", "title": "Jupyter notebooks"}, {"id": "e198570d-1da8-4b00-963f-e4190d174b85", "type": "concept", "title": "Markdown cells"}, {"id": "16d75442-b6df-4b81-af21-6c3a1293569c", "type": "concept", "title": "narrated analysis"}], "description": "Students use notebooks to combine code, outputs, explanation, and methodological notes."}, {"id": "fc447a87-8ec7-404c-ad51-ae4357217943", "type": "subtopic", "title": "Pandas fundamentals", "children": [{"id": "be742c36-9650-4058-9929-ce135de7977b", "type": "concept", "title": "DataFrames"}, {"id": "f4135d36-142a-48f6-b9de-fed5199ac99b", "type": "concept", "title": "groupby"}, {"id": "48eb9f8c-d04f-40a2-be33-c05d9170b174", "type": "concept", "title": "merge and concat"}], "description": "The course introduces loading, filtering, grouping, merging, cleaning, and exporting datasets."}, {"id": "c5fdc494-ba7f-47e3-a314-a0eb4a1f2e18", "type": "subtopic", "title": "Reproducible project structure", "children": [{"id": "df0a5c1d-0f13-4621-9664-58c5eeed6dfc", "type": "concept", "title": "folder structure"}, {"id": "ff47c023-7bfb-4908-8f79-ded63cb42f4c", "type": "concept", "title": "requirements files"}, {"id": "6b7cc9b6-c3ae-48e8-8cd0-a589b6b1f2c3", "type": "concept", "title": "README methodology"}], "description": "Students build habits that let editors, collaborators, and future readers inspect the work."}, {"id": "768757ba-0957-470f-a1ce-e609d5d10803", "type": "subtopic", "title": "Version control basics", "children": [{"id": "ef69fbc6-4ea4-4e86-8d2d-64e7f9709072", "type": "concept", "title": "commits"}, {"id": "d73fc266-99f3-4378-9b6f-d8e81cbb6551", "type": "concept", "title": "branches"}, {"id": "0599ee59-eabb-49d2-aeed-10ada32fb135", "type": "concept", "title": "data exclusions"}], "description": "Students use Git or similar tools for analysis history, collaboration, and rollback."}]}, {"id": "268fb953-5004-4e57-8308-e38be784e872", "type": "topic", "title": "Verification, Methodology, and Editorial Standards", "description": "Data journalism is still journalism: every number needs a source, every transformation needs a reason, and every claim needs editorial testing.", "children": [{"id": "e7416d14-a644-40e1-baa5-36548f55fde4", "type": "subtopic", "title": "Replicating findings", "children": [{"id": "4edaf714-a506-4514-90af-08ca726ca5c6", "type": "concept", "title": "independent checks"}, {"id": "3d52896c-e1ae-4933-a0fc-efc5339bddb4", "type": "concept", "title": "spot checks"}, {"id": "7fc5a46b-8165-469f-96fa-eebd43ddf612", "type": "concept", "title": "edge cases"}], "description": "Students learn to rerun analysis, compare outputs, and catch fragile claims before publication."}, {"id": "2d341a09-1250-4965-aca7-94fda0a0c104", "type": "subtopic", "title": "Triangulating with human reporting", "children": [{"id": "b01de1fe-a571-4476-ac93-92ca8c150015", "type": "concept", "title": "expert vetting"}, {"id": "329e2b5f-b858-4958-9fd0-4496f5bdf589", "type": "concept", "title": "affected-source interviews"}, {"id": "74117651-cfde-4d2e-b145-14755540a44d", "type": "concept", "title": "document corroboration"}], "description": "The unit connects quantitative findings with interviews, documents, observation, and expert review."}, {"id": "6aa4a8c7-f391-4b6a-b41c-195ad13c1c08", "type": "subtopic", "title": "Methodology writing", "children": [{"id": "f2dac3d9-fab7-488a-b88e-d2b3d21f8c72", "type": "concept", "title": "method boxes"}, {"id": "7c7e2397-ab6c-4272-8d20-5d2f1d2f8fbf", "type": "concept", "title": "limitations"}, {"id": "ba80d7d6-737d-4efc-9ed2-2259ff2642ed", "type": "concept", "title": "corrections readiness"}], "description": "Students practice explaining data sources, cleaning choices, limitations, and uncertainty in plain language."}, {"id": "e5a5548c-bcd7-4763-880e-9772c36937ba", "type": "subtopic", "title": "Editorial review for numbers", "children": [{"id": "08e59a12-30c6-4b96-8754-618c85484991", "type": "concept", "title": "claim-evidence matching"}, {"id": "50a0eee2-669a-4a0b-b42d-124eb5ddeddb", "type": "concept", "title": "headline discipline"}, {"id": "8856e8f6-4b59-47fb-a61a-863d56e67ce5", "type": "concept", "title": "copy-editing numbers"}], "description": "Students learn newsroom-style checks for calculations, chart labels, headlines, and claims."}]}, {"id": "bfdcb0b4-fed4-46a0-892a-b889118a7cb6", "type": "topic", "title": "Data Visualization, Accessibility, and Visual Ethics", "description": "Students learn to make graphics that clarify evidence instead of decorating it. The focus is chart choice, accuracy, accessibility, and editorial judgment.", "children": [{"id": "cb328bac-9d23-49d2-b391-2334c8f800fd", "type": "subtopic", "title": "Chart selection", "children": [{"id": "e82c60ff-fe48-41d0-bda6-16e0361ab2f4", "type": "concept", "title": "bar charts"}, {"id": "5a3e1fb1-5684-459e-999c-cd6d5bcbfcc4", "type": "concept", "title": "line charts"}, {"id": "90351f13-e14c-479b-865b-0cad2d5f86cb", "type": "concept", "title": "scatterplots"}], "description": "Students match visual forms to comparisons, distributions, rankings, change over time, and parts of a whole."}, {"id": "c222d299-43cb-4fb5-9ac6-ecc409207dbc", "type": "subtopic", "title": "Annotation and narrative flow", "children": [{"id": "7a17da71-d158-41f3-9614-84a3d1b6905e", "type": "concept", "title": "active titles"}, {"id": "4b294c8c-017e-4e4c-82cc-eb8cd7856b88", "type": "concept", "title": "source notes"}, {"id": "8e54e1dc-efec-4073-b6fd-60c3b2385741", "type": "concept", "title": "visual hierarchy"}], "description": "The class shows how titles, labels, notes, and callouts guide readers through evidence."}, {"id": "c17a9195-d752-4d62-ace0-65c7c3723486", "type": "subtopic", "title": "Avoiding visual distortion", "children": [{"id": "c3b7bbd3-5534-4908-9fb7-995a03f7a561", "type": "concept", "title": "axis choices"}, {"id": "c4891085-ea64-4a83-acff-f02dd5cb6c16", "type": "concept", "title": "binning"}, {"id": "675b7006-e916-40eb-bd4c-4b27ba356a8e", "type": "concept", "title": "color misuse"}], "description": "Students identify misleading scales, truncated axes, inappropriate aggregations, and over-designed graphics."}, {"id": "2405b7d3-796a-45be-8ad1-2a5a89bc11f6", "type": "subtopic", "title": "Accessible graphics", "children": [{"id": "6bb11bc2-4ef3-4409-ad64-c7b0c658422c", "type": "concept", "title": "color contrast"}, {"id": "712df913-c2c0-4b7e-9b3c-668ed2e720a7", "type": "concept", "title": "alt text"}, {"id": "05dff264-82ef-4a1b-ad90-051a9fc1a6fa", "type": "concept", "title": "responsive charts"}], "description": "Students design for mobile screens, color-vision differences, alt text, and readers using assistive technology."}]}, {"id": "9171ebd1-1eb5-4d9d-9ebe-710836466c7f", "type": "topic", "title": "Mapping and Geographic Data", "description": "This section develops spatial literacy so students can report place-based patterns without making the common mistakes maps invite.", "children": [{"id": "ea4416b7-4520-4c8d-8b4f-a47a25bbdcda", "type": "subtopic", "title": "Geographic data basics", "children": [{"id": "4d78cf22-9b0e-4597-b1a1-cd5682e19bdc", "type": "concept", "title": "latitude/longitude"}, {"id": "b9554e9f-33e3-481c-b51c-5ad6ac9c77e4", "type": "concept", "title": "GeoJSON"}, {"id": "55e59137-6ef2-48f0-93f0-5f15727ff162", "type": "concept", "title": "shapefiles"}], "description": "Students learn coordinates, boundaries, projections, geocoding, and common spatial file formats."}, {"id": "736def2b-4482-43ca-a774-08d3263e5490", "type": "subtopic", "title": "Choropleths and rate maps", "children": [{"id": "a2fb6a72-d6c5-4bb3-bc38-5071b046800a", "type": "concept", "title": "normalization"}, {"id": "a1655b6b-4eb4-442f-bbe1-70a919d9bb26", "type": "concept", "title": "classification bins"}, {"id": "1b9a2985-8b22-4110-aefe-5289538017e3", "type": "concept", "title": "small-area caution"}], "description": "The unit emphasizes when to map rates instead of raw counts and how classification choices affect interpretation."}, {"id": "e5da44c2-4e8c-44a2-86f9-ee3b2608a876", "type": "subtopic", "title": "Spatial joins and proximity", "children": [{"id": "391e84e0-1edc-4f9e-bccb-67bc12ddb5aa", "type": "concept", "title": "point-in-polygon"}, {"id": "ede59bab-4fee-4640-8ac9-fe1a12d926be", "type": "concept", "title": "buffers"}, {"id": "6c7bf001-1327-4aa2-b7cf-7d289ccd5d8a", "type": "concept", "title": "geocoding accuracy"}], "description": "Students learn to connect places to other records while checking for boundary and precision problems."}, {"id": "4c545159-d673-4efa-82fc-499472c04cd5", "type": "subtopic", "title": "Localizing spatial stories", "children": [{"id": "ef405704-8adc-43e5-8245-469774496856", "type": "concept", "title": "neighborhood comparisons"}, {"id": "3af05a9b-4924-4d10-8f1f-123c573e34e0", "type": "concept", "title": "field reporting"}, {"id": "565d43a8-7d25-4bbd-bbc2-d88fb8ed8946", "type": "concept", "title": "ground-truthing"}], "description": "Students use maps to find reporting targets and then return to interviews and documents."}]}, {"id": "623ac1c3-e5ca-4fc5-bcbc-6d0033019397", "type": "topic", "title": "Scraping, APIs, and Document Extraction", "description": "When data is not offered neatly, reporters need lawful, ethical, and reliable acquisition methods. This unit introduces practical collection workflows.", "children": [{"id": "e9c8bcdf-6079-4231-b6e2-9dc7bb3b1d99", "type": "subtopic", "title": "Web scraping fundamentals", "children": [{"id": "0df926de-95b6-43c2-a237-235fce945b83", "type": "concept", "title": "HTML tables"}, {"id": "4d939bb5-25dd-421d-a940-005b8ceefb49", "type": "concept", "title": "robots and terms"}, {"id": "edab62b2-9423-4708-ba65-0391b57c45dc", "type": "concept", "title": "rate limits"}], "description": "Students learn how pages are structured and when scraping is appropriate."}, {"id": "f3bd622a-c0ce-4745-af5f-87b918a63c42", "type": "subtopic", "title": "APIs and structured feeds", "children": [{"id": "1a871232-96ee-4251-befc-ecc719a5d648", "type": "concept", "title": "requests"}, {"id": "c6fc0468-6df9-47f4-8687-89bc4ebc6440", "type": "concept", "title": "JSON parsing"}, {"id": "dd3228a3-e731-42c9-8113-8e1e7d49a4d9", "type": "concept", "title": "pagination"}], "description": "The class introduces endpoints, parameters, JSON, authentication, and pagination."}, {"id": "c18d90b4-9f48-41b7-820b-0c0705d91c7b", "type": "subtopic", "title": "PDF and document extraction", "children": [{"id": "10336157-9f65-4d5c-9c7a-b0c3762aefab", "type": "concept", "title": "OCR"}, {"id": "e82084dc-38a5-48ec-ae76-23662d5f50b4", "type": "concept", "title": "table extraction"}, {"id": "f746113b-0df9-4c0e-9360-bd812e59dfd1", "type": "concept", "title": "manual validation"}], "description": "Students practice extracting tables and text from PDFs while checking against originals."}, {"id": "fa9eb588-ecc8-4f01-849c-41389ae032c3", "type": "subtopic", "title": "Collection ethics and legality", "children": [{"id": "b8d81eff-6f31-4386-a9fd-0166eef47066", "type": "concept", "title": "minimization"}, {"id": "1425ef17-9465-4c31-992f-7b2e9e40c4f7", "type": "concept", "title": "responsible collection"}, {"id": "aad355f4-c203-4510-b2e9-d5fc382df3af", "type": "concept", "title": "editor consultation"}], "description": "Students consider privacy, site burden, terms of service, and public-interest justification."}]}, {"id": "92291fb5-c91c-4396-807e-5758d9ccc327", "type": "topic", "title": "Data Ethics, Privacy, Security, and Harm Reduction", "description": "Students learn that responsible data journalism protects people while holding institutions accountable. The unit treats ethics as part of method, not an afterthought.", "children": [{"id": "de179f78-d11a-441c-a019-42c82e27f037", "type": "subtopic", "title": "Privacy and identifiability", "children": [{"id": "14e6f433-8863-4065-872e-8f17ff5b3aca", "type": "concept", "title": "personally identifiable information"}, {"id": "b5c64286-34e5-4ba1-ab4b-f2dabc2fd67f", "type": "concept", "title": "reidentification risk"}, {"id": "c9a23c8a-853f-46a2-91c7-c7ca47a7fa80", "type": "concept", "title": "small-cell suppression"}], "description": "Students evaluate whether data can expose individuals directly or through linkage."}, {"id": "4f0b6911-1462-4de8-a199-0d5e434677d0", "type": "subtopic", "title": "Minimization and secure handling", "children": [{"id": "d27fb433-8c2b-4f15-8185-2cfaa8bc0e72", "type": "concept", "title": "encrypted storage"}, {"id": "3690e0e1-721e-4507-984f-9ea54fd091ee", "type": "concept", "title": "access controls"}, {"id": "a51076d9-e703-4af6-b3fc-fa0a01ddcfdf", "type": "concept", "title": "secure deletion"}], "description": "The class covers collecting only what is needed and protecting sensitive files, sources, and communications."}, {"id": "f998c6ce-658d-4154-9afa-0f66686b62b0", "type": "subtopic", "title": "Equity and representational harm", "children": [{"id": "ecb1b215-b743-482f-9992-8f9c8a7ab116", "type": "concept", "title": "biased categories"}, {"id": "a5e1b209-774d-4033-9a9d-ccae96a9069f", "type": "concept", "title": "administrative data limits"}, {"id": "7af2679c-f41d-4f39-90da-15b631067193", "type": "concept", "title": "community review"}], "description": "Students examine how categories, missing data, and institutional records can reinforce harm."}, {"id": "c052e846-9e1b-4ab7-a027-bf5e71173a2c", "type": "subtopic", "title": "Publishing decisions", "children": [{"id": "696db4a7-b4f9-4937-a13c-41566869182d", "type": "concept", "title": "redaction"}, {"id": "b35a45c0-2416-44e9-bb36-9893804e2c84", "type": "concept", "title": "aggregation"}, {"id": "ab65c194-75a8-46b5-acc0-622b193353d0", "type": "concept", "title": "public-interest balancing"}], "description": "Students learn when not to publish raw data, names, maps, or precise locations."}]}, {"id": "e8804d40-eb0b-4da7-94bc-f20cc14371a8", "type": "topic", "title": "Algorithmic Accountability and Computational Investigations", "description": "This advanced unit introduces reporting on systems that make or influence decisions: algorithms, automated tools, risk scores, and platform processes.", "children": [{"id": "ca8cd5ef-3ac0-407c-bb58-db96879ab21f", "type": "subtopic", "title": "Finding algorithmic power", "children": [{"id": "18ecd7fe-de34-480c-b5b7-2d5da799c4e7", "type": "concept", "title": "decision systems"}, {"id": "54b64414-c7b8-44e9-a0fc-a780b3716c91", "type": "concept", "title": "procurement records"}, {"id": "add9eee6-b2ef-43d4-86be-daa0676ccfb0", "type": "concept", "title": "vendor claims"}], "description": "Students identify where automated systems shape access, policing, employment, benefits, education, or information."}, {"id": "370946f1-8580-4410-a44b-558c89d1431f", "type": "subtopic", "title": "Auditing inputs and outcomes", "children": [{"id": "f8f37d6f-8cfe-4054-aae2-1807688a3023", "type": "concept", "title": "disparate impact"}, {"id": "3c7f2757-135b-4c27-9031-3e6a266402fc", "type": "concept", "title": "benchmarking"}, {"id": "324828a2-fe25-403e-88f7-63ba16df278e", "type": "concept", "title": "black-box testing"}], "description": "The class explores how reporters test systems using records, samples, simulations, and outcome analysis."}, {"id": "290b5ee6-3407-4f24-8873-6cb0f6daee9c", "type": "subtopic", "title": "Interpreting models cautiously", "children": [{"id": "ca7b9e36-a8b3-41ff-ab96-56539f4691dc", "type": "concept", "title": "proxy variables"}, {"id": "256eb6e4-5687-4e1f-a9a3-420b40beaf53", "type": "concept", "title": "false positives"}, {"id": "06f0251d-9793-4e34-abcb-5cd60a533e29", "type": "concept", "title": "model drift"}], "description": "Students learn the limits of prediction, correlation, proxies, and opaque vendor systems."}, {"id": "b5bbc2bb-53b7-4ac0-9800-4474da170f84", "type": "subtopic", "title": "Explaining technical findings", "children": [{"id": "90f6fc3b-d097-4203-8154-19275b457d7a", "type": "concept", "title": "plain-language explainers"}, {"id": "ee17fe07-95b0-4d26-9659-c2b7569e80bb", "type": "concept", "title": "method transparency"}, {"id": "3ebe3804-e2bf-48df-a79b-04c3aceaf09e", "type": "concept", "title": "technical review"}], "description": "Students practice translating computational evidence into accurate, accessible accountability reporting."}]}, {"id": "04e1fecd-b6c5-4711-a77f-a7ca366e3c92", "type": "topic", "title": "Building and Publishing a Data-Driven Story", "description": "The capstone pulls together reporting, analysis, visualization, editing, and publication workflow into a professional story package.", "children": [{"id": "50265e14-26ed-40d6-9782-3d8bc720630a", "type": "subtopic", "title": "Story memo and pitch", "children": [{"id": "24d38707-1dd0-418a-84ca-5f0f32c63d74", "type": "concept", "title": "nut graf"}, {"id": "2ea88739-7e4d-4947-a6ad-568a3945a038", "type": "concept", "title": "evidence plan"}, {"id": "4e1d7992-c69e-4cf5-bbbc-b7cd2ea6fcb4", "type": "concept", "title": "editor questions"}], "description": "Students write a focused pitch that states the finding, evidence, stakes, sources, visuals, and remaining risks."}, {"id": "fb5d8804-b083-4413-b0c5-797436e9aa1f", "type": "subtopic", "title": "Integrated reporting package", "children": [{"id": "e8ed5548-9a50-41b6-b196-55fe881296cd", "type": "concept", "title": "human reporting"}, {"id": "4159b821-ec73-4a87-af59-bdba493ea540", "type": "concept", "title": "documents"}, {"id": "0e0e23d5-0f4e-431f-a4c6-5a67c042a1ba", "type": "concept", "title": "analysis-backed claims"}], "description": "The project combines analysis with interviews, documents, scene, context, and clear explanation."}, {"id": "d667c4af-56d1-4eb6-8d04-6b682c010649", "type": "subtopic", "title": "Visual and interactive production", "children": [{"id": "91d51be3-8aad-4534-bc8e-356b467235e9", "type": "concept", "title": "static graphics"}, {"id": "69193a86-8601-4b0c-85b3-84d8c6c8c1f3", "type": "concept", "title": "interactive charts"}, {"id": "1230cbc0-6736-4745-b365-c2143a6b780a", "type": "concept", "title": "maps and tables"}], "description": "Students select the right format for reader comprehension and newsroom capacity."}, {"id": "ce07428f-9e7c-4404-a66b-4b58da4147cc", "type": "subtopic", "title": "Publication checklist", "children": [{"id": "e8c1d524-cacc-4ddc-a6d8-a48eea55fc90", "type": "concept", "title": "fact-check memo"}, {"id": "a21c338f-29c1-4bf0-8316-d48987bb81ad", "type": "concept", "title": "source list"}, {"id": "73bc250d-a244-4e41-9256-0548270946a3", "type": "concept", "title": "post-publication updates"}], "description": "The course ends with a professional pre-publication review of data, methodology, language, accessibility, and corrections readiness."}]}], "dbBacked": true}$dajojson$::jsonb,
